// Filtrar deals con renovación en los próximos 60 días
const deals = $input.first().json.data || [];
const now = Date.now();
const WINDOW_DAYS = 60;
const expiring = [];

for (const deal of deals) {
  if (!deal.expected_close_date) continue;

  const closeDate = new Date(deal.expected_close_date).getTime();
  const daysUntilClose = Math.floor((closeDate - now) / 86400000);

  if (daysUntilClose >= 0 && daysUntilClose <= WINDOW_DAYS) {
    expiring.push({
      json: {
        deal_id: deal.id,
        title: deal.title,
        owner: deal.owner_name,
        value: deal.value,
        currency: deal.currency,
        close_date: deal.expected_close_date,
        days_until_renewal: daysUntilClose,
        last_activity_date: deal.last_activity_date,
        days_since_activity: deal.last_activity_date
          ? Math.floor((now - new Date(deal.last_activity_date).getTime()) / 86400000)
          : 999,
      }
    });
  }
}

return expiring.length > 0
  ? expiring
  : [{ json: { action: 'no_renewals_upcoming', checked: deals.length } }];

// Combinar deal + health score y determinar acción
const deal = $input.first().json;
const health = $input.last().json; // puede ser array
const healthData = Array.isArray(health) ? health[0] : health;

const score = healthData?.score ?? 50; // default 50 si no hay datos
const riskLevel = healthData?.risk_level ?? 'medium';

let action, urgency, taskSubject, taskNote;

if (score >= 70) {
  action = 'auto_renewal_email';
  urgency = 'low';
  taskSubject = `Renovación próxima — ${deal.title} (${deal.days_until_renewal}d)`;
  taskNote = `Score ${score}/100 — Buen estado. Enviar email de renovación automático.`;
} else if (score >= 50) {
  action = 'csm_proactive_call';
  urgency = 'medium';
  taskSubject = `⚡ Iniciar conversación renovación — ${deal.title}`;
  taskNote = `Score ${score}/100 — Riesgo medio. Llamar esta semana para iniciar conversación de renovación. Renovación en ${deal.days_until_renewal} días.`;
} else {
  action = 'move_to_renegotiation';
  urgency = 'high';
  taskSubject = `🚨 MOVER A RENEGOCIACIÓN — ${deal.title}`;
  taskNote = `Score ${score}/100 — RIESGO ALTO. Mover a etapa Renegociación y activar playbook urgente. Renovación en ${deal.days_until_renewal} días.`;
}

return [{
  json: {
    ...deal,
    score,
    risk_level: riskLevel,
    action,
    urgency,
    task_subject: taskSubject,
    task_note: taskNote,
  }
}];
